/* -----------------------------------------------------------------------
 * ui_state_machine.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: Tony; Brendon (integrator) added the 28 Oct 2026 demo states (speaker lockout, battery time, fault and debug screens) and the 29-30 Oct 2026 effect-file fields and the two rules for following Jack (with an AI coding assistant).
 * BJT2 Sound Modulating Toy — UI State Machine Implementation
 * Author: Tony (Display/UI subsystem)
 *
 * Implements a home-screen-based UI state machine. The home screen is
 * the root, all other screens (Record, Play, Effects, Volume, File,
 * Battery) are reached through it by selecting a home menu item.
 *
 * Pattern: event-driven dispatcher.
 *   ui_process_event() handles EVENT_GO_HOME globally, then routes all
 *   other events to a private per-screen handler. Each handler only acts
 *   on events valid for its screen, everything else falls through
 *   silently, making cross-screen state corruption impossible.
 *
 * Special case — encoder push:
 *   The encoder push-switch (EVENT_MUTE_TOGGLE) means "select" on the
 *   Home, Effects and File screens and Mute on every other screen, the
 *   Volume screen included. ui_process_event() checks the screen before
 *   routing. BACK (EVENT_GO_HOME) always goes Home.
 *
 * Special case — Fault screen (modal overlay):
 *   ui_show_fault() opens it over whatever screen is showing and
 *   remembers that screen. While it is up, the first thing
 *   ui_process_event() does is dismiss it on ANY event and return —
 *   the event is used up, so a button press, encoder step or tap that
 *   closes the fault never also acts on the screen underneath.
 *
 * Special case — Debug screen (hidden):
 *   ui_enter_debug() opens it from Home only. While it shows, it is also
 *   handled before the global events: short BACK leaves, the encoder
 *   moves the debug_menu.c cursor, and every other event changes nothing,
 *   because push / PLAY / REC are the debug page's own actions there.
 *
 * Two rules for the firmware glue, to follow Jack's status:
 *   ui_follow_jack_idle()  when the UI follows Jack to idle (the seq rule)
 *   ui_rec_clock_start()   when the Record screen's clock starts
 *
 * The screens (ui_screen_t), one line each:
 *   HOME      six tiles: a tap opens one; the encoder moves the
 *             highlight and a push opens the highlighted one
 *   RECORD    Start Recording / Stop Recording rows
 *   PLAY      one play / pause button; the encoder sets the volume
 *   EFFECTS   six effects: the encoder moves the cursor, a push or a tap
 *             on a row turns that effect on (or off again)
 *   VOLUME    - / + / mute buttons; the encoder sets the volume
 *   FILE      Up, Down, Select (play), Delete; the encoder scrolls
 *   BATTERY   display only
 *   FAULT     modal, over any screen: any input closes it
 *   DEBUG     hidden: BACK held 2 s on Home opens it, a short BACK closes it
 * Moving between them: BACK goes Home from every screen but FAULT (and
 * stops a paused file); PLAY
 * when idle opens PLAY; REC when not recording opens RECORD; a fault
 * opens FAULT, which returns to the screen it covered. (FILE -> PLAY on
 * Select is done by tony_ui.c, which also starts the file.)
 *
 * The transport (playback_state_t); PLAY and REC act on it from every
 * screen but FAULT and DEBUG:
 *   IDLE      -> RECORDING   REC, or Start Recording
 *   RECORDING -> IDLE        REC again, or Stop Recording
 *   IDLE      -> PLAYING     PLAY
 *   PLAYING  <-> PAUSED      PLAY
 *   PAUSED    -> IDLE        BACK (going Home stops a paused file)
 *   PLAYING or PAUSED -> RECORDING   REC (playback loops, so a recording
 *                                     replaces it)
 * tony_ui.c turns each change into a command for Jack, and also sets IDLE
 * itself when Jack says he has stopped (ui_follow_jack_idle).
 *
 * No task of its own: tony_ui.c calls ui_process_event() inside
 * TonyTask, once per input event.
 * No HAL functions are called. This file compiles on any host.
 * ----------------------------------------------------------------------- */

#include "ui_state_machine.h"
#include "debug_menu.h"
#include <stddef.h>

/* ------------------------------------------------------------------
 * Forward declarations — private per-screen handlers
 * ------------------------------------------------------------------ */
static void handle_home(ui_state_t *s, ui_event_t e);
static void handle_record(ui_state_t *s, ui_event_t e);
static void handle_play(ui_state_t *s, ui_event_t e);
static void handle_effects(ui_state_t *s, ui_event_t e);
static void handle_volume(ui_state_t *s, ui_event_t e);
static void handle_file(ui_state_t *s, ui_event_t e);
static void handle_battery(ui_state_t *s, ui_event_t e);
static void handle_debug(ui_state_t *s, ui_event_t e);

/* -----------------------------------------------------------------------
 * ui_init
 * Sets all fields to safe defaults. Must be called before first
 * ui_process_event call.
 * ----------------------------------------------------------------------- */
void ui_init(ui_state_t *s)
{
    if (s == NULL) {
        return;
    }
    s->screen             = UI_SCREEN_HOME;
    s->playback           = PLAYBACK_IDLE;
    s->home_highlighted   = UI_SCREEN_RECORD;  /* cursor on first item */
    s->active_effect      = EFFECT_NONE;
    s->effect_highlighted = EFFECT_1;
    s->volume             = UI_VOLUME_DEFAULT;
    s->muted        = false;
    s->battery_pct  = 0U;
    s->battery_mv   = 0U;
    /* No battery message yet: no current, no time estimate, "No gauge". */
    s->battery_ma_now   = 0;
    s->battery_ma_avg   = 0;
    s->battery_tte_min  = UI_TIME_UNKNOWN;
    s->battery_ttf_min  = UI_TIME_UNKNOWN;
    s->battery_charging = false;
    s->battery_valid    = false;
    s->battery_low           = false;
    s->battery_critical      = false;
    s->battery_soc_override  = false;
    s->battery_ext_power     = false;
    s->battery_charger_fault = false;
    s->sd_status    = SD_STATUS_OK;
    s->file_index   = 0U;
    s->file_count   = 0U;
    s->error_active = false;
    s->prep_pct     = UI_PREP_NONE;     /* no effect file is being waited for */
    s->fx_na        = false;
    s->speaker_locked = false;
    s->fault_return_screen = UI_SCREEN_HOME;
    s->fault_source   = (uint8_t)UI_FAULT_SRC_SYSTEM;
    s->fault_code     = 0U;
    s->fault_line2[0] = '\0';
    s->fault_line3[0] = '\0';
    s->debug_page     = (uint8_t)DEBUG_PAGE_SYSTEM;
    s->debug_item     = 0U;
}

/* -----------------------------------------------------------------------
 * ui_enter_debug
 * Home only, so the hidden screen can never open on top of a recording
 * screen, a fault, or itself (which would reset the cursor). Always
 * starts on the System page: the page the stack check is read from.
 * ----------------------------------------------------------------------- */
void ui_enter_debug(ui_state_t *s)
{
    if (s == NULL || s->screen != UI_SCREEN_HOME) {
        return;
    }
    s->screen     = UI_SCREEN_DEBUG;
    s->debug_page = (uint8_t)DEBUG_PAGE_SYSTEM;
    s->debug_item = 0U;
}

/* Copy one line of fault text, cut to UI_FAULT_TEXT_MAX - 1 = 20
 * characters (one size-2 line on the panel). NULL gives an empty line. */
static void copy_fault_text(char *dst, const char *src)
{
    size_t n = 0U;
    if (src != NULL) {
        while (n < (UI_FAULT_TEXT_MAX - 1U) && src[n] != '\0') {
            dst[n] = src[n];
            n++;
        }
    }
    dst[n] = '\0';
}

/* -----------------------------------------------------------------------
 * ui_show_fault
 * Opens the fault overlay, or updates it. The return screen is taken
 * only when the overlay opens, so a second, different fault that
 * arrives while the first is still showing replaces the text but still
 * returns the user to where they were before the first one.
 * ----------------------------------------------------------------------- */
bool ui_show_fault(ui_state_t *s, uint8_t source, uint8_t code,
                   const char *line2, const char *line3)
{
    if (s == NULL) {
        return false;
    }
    if (s->screen == UI_SCREEN_FAULT) {
        if (s->fault_source == source && s->fault_code == code) {
            return false;               /* the same fault again: nothing new */
        }
    } else {
        s->fault_return_screen = s->screen;
        s->screen = UI_SCREEN_FAULT;
    }
    s->fault_source = source;
    s->fault_code   = code;
    copy_fault_text(s->fault_line2, line2);
    copy_fault_text(s->fault_line3, line3);
    return true;
}

/* -----------------------------------------------------------------------
 * ui_process_event
 * Top-level dispatcher, in this order:
 *   1. the fault overlay (any event only closes it)
 *   2. the debug screen (its own three events)
 *   3. the global events: BACK (EVENT_GO_HOME) always goes Home; the
 *      encoder push (EVENT_MUTE_TOGGLE) selects on Home, Effects and
 *      File and toggles mute everywhere else; PLAY and REC
 *   4. everything else goes to the handler of the screen showing.
 * ----------------------------------------------------------------------- */
void ui_process_event(ui_state_t *s, ui_event_t e)
{
    if (s == NULL) {
        return;
    }

    /* ------------------------------------------------------------------
     * FAULT OVERLAY — checked before everything else.
     * Any real event (button, encoder push or turn, touch anywhere)
     * closes it and is consumed here: nothing else changes, so the same
     * press cannot also mute, start playback or navigate underneath.
     * EVENT_NONE is "no input" and leaves the fault showing.
     * ------------------------------------------------------------------ */
    if (s->screen == UI_SCREEN_FAULT) {
        if (e < EVENT_NONE) {
            s->screen = (s->fault_return_screen < UI_SCREEN_COUNT &&
                         s->fault_return_screen != UI_SCREEN_FAULT)
                        ? s->fault_return_screen : UI_SCREEN_HOME;
        }
        return;
    }

    /* ------------------------------------------------------------------
     * DEBUG SCREEN — also checked before the global events.
     * Push, PLAY and REC are the debug page's own actions (the firmware
     * glue plays a test pattern, injects a fault ...), so they must not
     * also mute, start playback or recording, or jump to another screen
     * as the global handlers below would.
     * ------------------------------------------------------------------ */
    if (s->screen == UI_SCREEN_DEBUG) {
        handle_debug(s, e);
        return;
    }

    /* ------------------------------------------------------------------
     * GLOBAL EVENTS — handled before screen routing.
     * These work identically regardless of which screen is active.
     * Touch and physical buttons both produce these same events.
     * ------------------------------------------------------------------ */

    /* Back button — always navigate to home, no exceptions */
    /* TEAM CODE (written by Brendon, 30 Oct 2026): BACK stops a paused file.
     * A paused file keeps the SD card in use (the footer shows SD BUSY) and
     * the Play screen has no Stop button, so going Home from PAUSED stops
     * it: tony_ui.c turns PAUSED -> IDLE into JACK_CMD_PLAY_STOP. A file
     * that is PLAYING keeps looping, and a recording carries on. */
    if (e == EVENT_GO_HOME) {
        if (s->playback == PLAYBACK_PAUSED) {
            s->playback = PLAYBACK_IDLE;
        }
        s->screen = UI_SCREEN_HOME;
        return;
    }

    /* Encoder push — context-aware based on current screen.
     *
     * Screens with a selectable item: push = select (not mute).
     *   Home    --> navigate into highlighted screen
     *   Effects --> toggle highlighted effect on/off
     *   File    --> confirm file selection
     *
     * All other screens: push = mute toggle.
     * Mute is most useful when audio is actively playing and the
     * user needs to silence it without navigating anywhere. */
    if (e == EVENT_MUTE_TOGGLE) {
        if (s->screen == UI_SCREEN_HOME    ||
            s->screen == UI_SCREEN_EFFECTS ||
            s->screen == UI_SCREEN_FILE) {
            /* Route to screen handler — each handles push as select */
            switch (s->screen) {
                case UI_SCREEN_HOME:    handle_home(s, e);    break;
                case UI_SCREEN_EFFECTS: handle_effects(s, e); break;
                case UI_SCREEN_FILE:    handle_file(s, e);    break;
                default: break;
            }
        } else {
            s->muted = !s->muted;
        }
        return;
    }

    /* Play/Pause button — context-aware global action:
     *   IDLE    -> navigate to Play screen and start playing
     *   PLAYING -> pause
     *   PAUSED  -> resume playing
     * Touch on the Play screen produces the same result via
     * EVENT_PLAY_START / EVENT_PLAY_PAUSE routed below. */
    if (e == EVENT_BTN_PLAYPAUSE) {
        if (s->playback == PLAYBACK_IDLE) {
            s->screen   = UI_SCREEN_PLAY;
            s->playback = PLAYBACK_PLAYING;
        } else if (s->playback == PLAYBACK_PLAYING) {
            s->playback = PLAYBACK_PAUSED;
        } else if (s->playback == PLAYBACK_PAUSED) {
            s->playback = PLAYBACK_PLAYING;
        }
        return;
    }

    /* Record button — context-aware global action:
     *   IDLE      -> navigate to Record screen and start recording
     *   PLAYING / PAUSED -> the same (playback loops forever, so recording
     *               replaces it; the firmware stops playback first)
     *   RECORDING -> stop recording
     * Touch on the Record screen produces the same result via
     * EVENT_RECORD_START / EVENT_RECORD_STOP routed below. */
    if (e == EVENT_BTN_RECORD) {
        if (s->playback != PLAYBACK_RECORDING) {
            s->screen   = UI_SCREEN_RECORD;
            s->playback = PLAYBACK_RECORDING;
        } else if (s->playback == PLAYBACK_RECORDING) {
            s->playback = PLAYBACK_IDLE;
        }
        return;
    }

    /* Route all remaining events to the active screen handler */
    switch (s->screen) {
        case UI_SCREEN_HOME:    handle_home(s, e);    break;
        case UI_SCREEN_RECORD:  handle_record(s, e);  break;
        case UI_SCREEN_PLAY:    handle_play(s, e);    break;
        case UI_SCREEN_EFFECTS: handle_effects(s, e); break;
        case UI_SCREEN_VOLUME:  handle_volume(s, e);  break;
        case UI_SCREEN_FILE:    handle_file(s, e);    break;
        case UI_SCREEN_BATTERY: handle_battery(s, e); break;
        default:
            s->screen = UI_SCREEN_HOME;
            break;
    }
}

/* -----------------------------------------------------------------------
 * ui_get_effective_volume
 * Returns 0 when muted; otherwise returns the stored volume.
 * Mute is a zero-override, not state destruction — s->volume is always
 * preserved so unmuting restores the previous level.
 * ----------------------------------------------------------------------- */
uint8_t ui_get_effective_volume(const ui_state_t *s)
{
    if (s == NULL) {
        return 0U;
    }
    return s->muted ? 0U : s->volume;
}

/* -----------------------------------------------------------------------
 * ui_follow_jack_idle
 * The seq rule: a status that carries Tony's newest command number shows
 * Jack after that command, so it is trusted at once. Without it, the old
 * 1 s rule stays as the fallback. jack_playing 3 ("preparing") is not
 * idle: the file plays by itself once it is made.
 * ----------------------------------------------------------------------- */
bool ui_follow_jack_idle(playback_state_t ui_playback, bool jack_recording, uint8_t jack_playing,
                         bool seq_matches, uint32_t ms_since_cmd)
{
    bool jack_idle = !jack_recording && jack_playing == 0U;

    if (!jack_idle || ui_playback == PLAYBACK_IDLE) {
        return false;
    }
    return seq_matches || ms_since_cmd > UI_CMD_RECONCILE_MS;
}

/* -----------------------------------------------------------------------
 * ui_rec_clock_start
 * Start the Record screen's clock when the UI and Jack both say
 * "recording" and it is not running yet: on his status or his RECORD_START
 * ack, whichever Tony reads first (usually the status).
 * ----------------------------------------------------------------------- */
bool ui_rec_clock_start(playback_state_t ui_playback, bool jack_recording, bool clock_running)
{
    return ui_playback == PLAYBACK_RECORDING && jack_recording && !clock_running;
}

/* -----------------------------------------------------------------------
 * handle_home  (private)
 * Processes menu item selection on the home screen.
 * Each navigation event transitions to the corresponding child screen.
 * ----------------------------------------------------------------------- */
/* -----------------------------------------------------------------------
 * handle_home  (private)
 *
 * Touch tap navigates directly to the tapped screen.
 * Encoder CW/CCW scrolls the highlight cursor through all six items,
 * wrapping at both ends.
 * Encoder push (EVENT_MUTE_TOGGLE) navigates to the highlighted screen.
 *
 * Home screen order matches the visual layout, read row by row (three
 * rows of two tiles):
 *   Record → Play → Effects → Volume → File → Battery
 * ----------------------------------------------------------------------- */
static void handle_home(ui_state_t *s, ui_event_t e)
{
    /* The six home screens in display order — used for encoder wrapping */
    static const ui_screen_t home_items[] = {
        UI_SCREEN_RECORD,
        UI_SCREEN_PLAY,
        UI_SCREEN_EFFECTS,
        UI_SCREEN_VOLUME,
        UI_SCREEN_FILE,
        UI_SCREEN_BATTERY,
    };
    static const uint8_t home_item_count = 6U;

    switch (e) {
        /* Touch tap — navigate directly, update highlight to match */
        case EVENT_NAV_RECORD:
            s->home_highlighted = UI_SCREEN_RECORD;
            s->screen = UI_SCREEN_RECORD;
            break;
        case EVENT_NAV_PLAY:
            s->home_highlighted = UI_SCREEN_PLAY;
            s->screen = UI_SCREEN_PLAY;
            break;
        case EVENT_NAV_EFFECTS:
            s->home_highlighted = UI_SCREEN_EFFECTS;
            s->screen = UI_SCREEN_EFFECTS;
            break;
        case EVENT_NAV_VOLUME:
            s->home_highlighted = UI_SCREEN_VOLUME;
            s->screen = UI_SCREEN_VOLUME;
            break;
        case EVENT_NAV_FILE:
            s->home_highlighted = UI_SCREEN_FILE;
            s->screen = UI_SCREEN_FILE;
            break;
        case EVENT_NAV_BATTERY:
            s->home_highlighted = UI_SCREEN_BATTERY;
            s->screen = UI_SCREEN_BATTERY;
            break;

        /* Encoder CW — scroll highlight down, wrap at bottom */
        case EVENT_VOLUME_UP: {
            uint8_t i;
            for (i = 0U; i < home_item_count; i++) {
                if (home_items[i] == s->home_highlighted) { break; }
            }
            i = (uint8_t)((i + 1U) % home_item_count);
            s->home_highlighted = home_items[i];
            break;
        }

        /* Encoder CCW — scroll highlight up, wrap at top */
        case EVENT_VOLUME_DOWN: {
            uint8_t i;
            for (i = 0U; i < home_item_count; i++) {
                if (home_items[i] == s->home_highlighted) { break; }
            }
            i = (uint8_t)((i + home_item_count - 1U) % home_item_count);
            s->home_highlighted = home_items[i];
            break;
        }

        /* Encoder push — navigate to highlighted item */
        case EVENT_MUTE_TOGGLE:
            s->screen = s->home_highlighted;
            break;

        default:
            break;
    }
}

/* -----------------------------------------------------------------------
 * handle_record  (private)
 *
 * Valid transitions:
 *   IDLE      + RECORD_START -> RECORDING
 *   RECORDING + RECORD_STOP  -> IDLE
 *
 * Invalid transitions (e.g. START while already recording) are
 * silently ignored to prevent accidental state corruption.
 * ----------------------------------------------------------------------- */
static void handle_record(ui_state_t *s, ui_event_t e)
{
    switch (e) {
        case EVENT_RECORD_START:
            if (s->playback != PLAYBACK_RECORDING) {   /* replaces a looping playback */
                s->playback = PLAYBACK_RECORDING;
            }
            break;
        case EVENT_RECORD_STOP:
            if (s->playback == PLAYBACK_RECORDING) {
                s->playback = PLAYBACK_IDLE;
            }
            break;
        default:
            break;
    }
}

/* -----------------------------------------------------------------------
 * handle_play  (private)
 *
 * Manages playback states, and the volume while listening.
 *
 * Valid transitions:
 *   IDLE    + PLAY_START -> PLAYING
 *   PLAYING + PLAY_PAUSE -> PAUSED
 *   PAUSED  + PLAY_PAUSE -> PLAYING   (pause toggles)
 *   PLAYING + PLAY_STOP  -> IDLE
 *   PAUSED  + PLAY_STOP  -> IDLE
 *   any     + PLAY_REPLAY-> PLAYING
 *   any     + VOLUME_UP / VOLUME_DOWN -> volume +1 / -1 (handle_volume)
 * No input sends PLAY_START, PLAY_PAUSE, PLAY_STOP or PLAY_REPLAY any
 * more: the Play screen's one button sends EVENT_BTN_PLAYPAUSE, handled
 * globally. They stay for the host tests. (The old autotune toggle is
 * gone: effects are picked on the Effects screen.)
 * ----------------------------------------------------------------------- */
static void handle_play(ui_state_t *s, ui_event_t e)
{
    switch (e) {
        case EVENT_PLAY_START:
            if (s->playback == PLAYBACK_IDLE) {
                s->playback = PLAYBACK_PLAYING;
            }
            break;

        case EVENT_PLAY_PAUSE:
            if (s->playback == PLAYBACK_PLAYING) {
                s->playback = PLAYBACK_PAUSED;
            } else if (s->playback == PLAYBACK_PAUSED) {
                s->playback = PLAYBACK_PLAYING;
            }
            break;

        case EVENT_PLAY_STOP:
            if (s->playback == PLAYBACK_PLAYING ||
                s->playback == PLAYBACK_PAUSED) {
                s->playback = PLAYBACK_IDLE;
            }
            break;

        case EVENT_PLAY_REPLAY:
            if (s->playback == PLAYBACK_IDLE   ||
                s->playback == PLAYBACK_PLAYING ||
                s->playback == PLAYBACK_PAUSED) {
                s->playback = PLAYBACK_PLAYING;
            }
            break;

        /* The encoder adjusts volume while listening, same as the Volume
         * screen (which stays for touch control). */
        case EVENT_VOLUME_UP:
        case EVENT_VOLUME_DOWN:
            handle_volume(s, e);
            break;

        default:
            break;
    }
}

/* -----------------------------------------------------------------------
 * handle_effects  (private)
 *
 * Encoder scrolls highlight cursor through EFFECT_1 to EFFECT_6.
 * Selecting the active effect toggles it off (back to EFFECT_NONE).
 * Selecting a different effect switches to it, deactivating the previous.
 * A tap on an effect row (EVENT_EFFECT_PICK_1..6) first moves the cursor
 * to that row, so the effect toggled is the one tapped.
 * ----------------------------------------------------------------------- */
_Static_assert((int)EVENT_EFFECT_PICK_6 - (int)EVENT_EFFECT_PICK_1 == (int)EFFECT_6 - (int)EFFECT_1,
               "one EVENT_EFFECT_PICK_n per effect, in effect order");

/* Select: the highlighted effect goes off if it is the active one,
 * otherwise it replaces the active one. */
static void toggle_highlighted_effect(ui_state_t *s)
{
    if (s->active_effect == s->effect_highlighted) {
        s->active_effect = EFFECT_NONE;
    } else {
        s->active_effect = s->effect_highlighted;
    }
}

static void handle_effects(ui_state_t *s, ui_event_t e)
{
    switch (e) {
        /* Scroll cursor up — accepts encoder event or dedicated scroll event.
         * EVENT_VOLUME_DOWN is used because encoder always produces volume
         * events regardless of screen — remapped here by context. */
        case EVENT_EFFECT_SCROLL_UP:
        case EVENT_VOLUME_DOWN:
            if (s->effect_highlighted > EFFECT_1) {
                s->effect_highlighted =
                    (ui_effect_t)((int)s->effect_highlighted - 1);
            } else {
                s->effect_highlighted = EFFECT_6;
            }
            break;

        /* Scroll cursor down */
        case EVENT_EFFECT_SCROLL_DOWN:
        case EVENT_VOLUME_UP:
            if (s->effect_highlighted < EFFECT_6) {
                s->effect_highlighted =
                    (ui_effect_t)((int)s->effect_highlighted + 1);
            } else {
                s->effect_highlighted = EFFECT_1;
            }
            break;

        /* Select highlighted effect — toggle on/off.
         * Accepts both EVENT_EFFECT_SELECT and encoder push
         * (EVENT_MUTE_TOGGLE). On this screen encoder push means select,
         * not mute — consistent with home screen push-to-select pattern. */
        case EVENT_EFFECT_SELECT:
        case EVENT_MUTE_TOGGLE:
            toggle_highlighted_effect(s);
            break;

        /* Touch tap on effect row k: that row becomes the cursor, then it
         * toggles like a select. (All six rows used to send SELECT, which
         * toggled the cursor's effect, Autotune after boot, whichever row
         * was tapped.) */
        case EVENT_EFFECT_PICK_1:
        case EVENT_EFFECT_PICK_2:
        case EVENT_EFFECT_PICK_3:
        case EVENT_EFFECT_PICK_4:
        case EVENT_EFFECT_PICK_5:
        case EVENT_EFFECT_PICK_6:
            s->effect_highlighted =
                (ui_effect_t)((int)EFFECT_1 + ((int)e - (int)EVENT_EFFECT_PICK_1));
            toggle_highlighted_effect(s);
            break;

        default:
            break;
    }
}

/* -----------------------------------------------------------------------
 * handle_volume  (private)
 *
 * Encoder CW/CCW adjusts volume, clamped to [UI_VOLUME_MIN, UI_VOLUME_MAX].
 * The - and + buttons send the same two events. Mute is not handled here:
 * the encoder push and the mute button send EVENT_MUTE_TOGGLE, which
 * ui_process_event() toggles before routing, and BACK (EVENT_GO_HOME)
 * goes Home there too. handle_play() passes the encoder on to here.
 * ----------------------------------------------------------------------- */
static void handle_volume(ui_state_t *s, ui_event_t e)
{
    switch (e) {
        case EVENT_VOLUME_UP:
            if (s->volume < UI_VOLUME_MAX) {
                s->volume++;
            }
            break;

        case EVENT_VOLUME_DOWN:
            if (s->volume > UI_VOLUME_MIN) {
                s->volume--;
            }
            break;

        /* EVENT_MUTE_TOGGLE is now handled globally in ui_process_event
         * before routing — it never reaches here. Kept as a no-op
         * for defensive completeness only. */
        default:
            break;
    }
}

/* -----------------------------------------------------------------------
 * handle_file  (private)
 *
 * Encoder scrolls through the file list. file_index is clamped to
 * [0, file_count - 1]. If file_count is 0, scrolling is ignored.
 * EVENT_FILE_SELECT confirms the currently highlighted file.
 * ----------------------------------------------------------------------- */
static void handle_file(ui_state_t *s, ui_event_t e)
{
    switch (e) {
        /* Scroll up through file list.
         * Accepts both dedicated scroll event and encoder volume event —
         * same remapping approach as handle_effects. */
        case EVENT_FILE_SCROLL_UP:
        case EVENT_VOLUME_DOWN:
            if (s->file_count > 0U && s->file_index > 0U) {
                s->file_index--;
            }
            break;

        /* Scroll down through file list */
        case EVENT_FILE_SCROLL_DOWN:
        case EVENT_VOLUME_UP:
            if (s->file_count > 0U &&
                s->file_index < (uint16_t)(s->file_count - 1U)) {
                s->file_index++;
            }
            break;

        /* Confirm selection - accepts touch tap or encoder push.
         * On file screen encoder push = select file, not mute. */
        case EVENT_FILE_SELECT:
        case EVENT_MUTE_TOGGLE:
            /* Nothing changes here: the index is already set. In the
             * firmware, tony_ui.c turns a select made on this screen
             * into PLAY of the selected file and shows the Play screen. */
            break;

        /* Delete row: the firmware's two-tap confirm (delete_confirm.c)
         * decides, and Jack deletes; nothing in the UI state changes. */
        case EVENT_FILE_DELETE:
            break;

        default:
            break;
    }
}

/* -----------------------------------------------------------------------
 * handle_battery  (private)
 *
 * Battery screen is display-only. No user actions change state here.
 * battery_pct, battery_mv and the other battery fields are copied by
 * tony_ui.c (TonyTask) from Brendon's battery message (batteryQueue,
 * once a second, from his fuel gauge); no other task writes ui_state_t.
 * ----------------------------------------------------------------------- */
static void handle_battery(ui_state_t *s, ui_event_t e)
{
    /* No events are processed on the battery screen.
     * Suppress unused parameter warning. */
    (void)s;
    (void)e;
}

/* -----------------------------------------------------------------------
 * handle_debug  (private)
 *
 * Short BACK goes Home; the encoder walks the debug_menu.c cursor, which
 * changes page on the information pages and steps through the Speaker
 * and Faults lists item by item. Every other event changes nothing.
 * ----------------------------------------------------------------------- */
static void handle_debug(ui_state_t *s, ui_event_t e)
{
    switch (e) {
        case EVENT_GO_HOME:
            s->screen = UI_SCREEN_HOME;
            break;

        case EVENT_VOLUME_UP:           /* Encoder CW  — next item / page */
            debug_cursor_next(&s->debug_page, &s->debug_item);
            break;

        case EVENT_VOLUME_DOWN:         /* Encoder CCW — previous item / page */
            debug_cursor_prev(&s->debug_page, &s->debug_item);
            break;

        default:
            break;
    }
}
